      "stem": "依建築技術規則建築設計施工編規定，新建或增建建築物高度超過 21 公尺部分，在冬至日所造成之 日照陰影，應使鄰近之住宅區或商業區基地有 1 小時以上之有效日照。下列敘述何者錯誤？",
