      "year": "113",
      "subject": "建築結構",
      "number": 23,
      "stem": "土壤液化會造成完工後的建築物下陷或傾斜，下列針對土壤液化現象的敘述，何者錯誤？",
      "choices": [
        {
          "key": "A",
          "text": "觸發土壤液化的條件之一是建築物基礎底面的土壤承載力低，因此黏性土壤多的地層即屬 於土壤液化高風險區"
        },
        {
          "key": "B",
          "text": "觸發土壤液化的條件之一是該地土質為疏鬆的砂質土壤。在此類土層上興建建築物前，若 以重物重複錘擊地面夯實土壤，即可降低日後發生土壤液化的機會"
        },
        {
          "key": "C",
          "text": "觸發土壤液化的條件之一是土壤含水量達飽和狀態，因此在連日大雨過後，發生土壤液化 的機率會上升"
        },
        {
          "key": "D",
          "text": "觸發土壤液化的條件之一是土壤受到擾動，因此土壤液化時常發生在強震過後"
        }
      ],
      "answer": "A",
      "source": "建築師考古題/113_建築結構_試題.pdf",
      "answerSource": "建築師考古題/113_建築結構_答案.pdf",
      "officialUrl": "https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?e=113190&y=2024"
