      "stem": "如下圖所示，網釘工法是一種針對老舊建物外牆瓷磚改修的技術，其特性在於可最大限度地減少全面 打除舊瓷磚所造成之環境影響。此方法乃是先在既有外牆瓷磚的表面塗佈底料，再於其上鋪設合成纖 維網或玻璃纖維網 ， 並用錨釘固定以確保既有瓷磚不致掉落 ， 而後施以壓層塗料作為新的粉刷施作面 ， 其視設計需求可選用不同之面飾材。有關該工法的施作注意事項之敘述，下列何者錯誤？",
